with filtered_transactions as (select * from transactions where merchant is not null and account_id in (2, 8)), agg as (select case when merchant in ('Starbucks', '7-Eleven') then 'core' else 'other' end as merchant_group, max(amount) as max_amount, sum(case when merchant = '7-Eleven' then amount else 0 end) as 7_eleven_amount from filtered_transactions group by case when merchant in ('Starbucks', '7-Eleven') then 'core' else 'other' end) select merchant_group, max_amount, 7_eleven_amount from agg where 7_eleven_amount > 41;
